CREATE POLICY "videos_storage_read" ON storage.objects FOR SELECT USING (bucket_id = 'videos');
CREATE POLICY "videos_storage_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'videos' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "videos_storage_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'videos' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "videos_storage_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'videos' AND auth.uid()::text = (storage.foldername(name))[1]);